def get_total_number_of_sequences(m, n):
    def count_sequences(prev, length):
        # Base case: if the sequence length is 0, we've found a valid sequence
        if length == 0:
            return 1

        total = 0
        # Start from max(1, prev * 2) to ensure the current element satisfies the condition
        start = max(1, prev * 2)
        # Iterate through all valid values for the current element
        for i in range(start, m + 1):
            total += count_sequences(i, length - 1)
        return total

    # Start with prev = 0 to allow the first element to be any valid value
    return count_sequences(0, n)
