def sum_of_digits(numbers):
    def compute_digits_sum(num):
        if isinstance(num, int) and num >= 0:
            return sum(int(digit) for digit in str(num))
        return 0

    # Flatten the list if it contains nested lists
    flattened_numbers = []
    for element in numbers:
        if isinstance(element, list):
            flattened_numbers.extend(element)
        else:
            flattened_numbers.append(element)

    # Compute the total sum of digits for valid numbers in the flattened list
    return sum(compute_digits_sum(num) for num in flattened_numbers if isinstance(num, int) and num >= 0)
